const JSON_TYPE = /application\/json/i;

export async function fetchResource({ skillId, path, bridgeBase, fetcher }) {
  if (!skillId) throw new Error("fetchResource: skillId is required");
  if (!path) throw new Error("fetchResource: path is required");
  const doFetch = fetcher ?? globalThis.fetch;
  const base = String(bridgeBase ?? "").replace(/\/+$/, "");
  const url = `${base}/files/download`;

  const res = await doFetch(url, {
    method: "POST",
    headers: { "content-type": "application/json" },
    body: JSON.stringify({ skill_id: skillId, path }),
  });

  const raw = typeof res.arrayBuffer === "function"
    ? Buffer.from(await res.arrayBuffer())
    : Buffer.from(await res.text(), "utf-8");

  const envelope = parseEnvelope(raw, res.headers);
  if (envelope) {
    if (envelope.code !== 0) {
      throw new Error(typeof envelope.message === "string" && envelope.message
        ? envelope.message
        : `skill resource fetch failed (code ${envelope.code})`);
    }
    const data = envelope.data;
    if (data && typeof data.content === "string") {
      // An empty resource is a legitimate resource: decode it to a zero-byte Buffer.
      return data.encoding === "base64"
        ? Buffer.from(data.content, "base64")
        : Buffer.from(data.content, "utf-8");
    }
    throw new Error(typeof envelope.message === "string" && envelope.message
      ? envelope.message
      : `skill resource ${path} has no string content in envelope`);
  }
  return raw;
}

